def translate(text, language='en'):
    return PT.get(text, text) if language == 'pt' else text


def format_money(value, language='en'):
    if language == 'pt':
        return f'{Decimal(str(value)):,.2f}'.replace(',', '_').replace('.', ',').replace('_', '.')
    return str(value)

